let count = 0; // inferred: number
count = 'ten'; // Error: Type 'string' is not assignable to type 'number'.

const city = 'Pune'; // inferred: the literal type 'Pune', because a const never changes

function formatPrice(cents: number, currency = 'USD'): string {
  return new Intl.NumberFormat('en', { style: 'currency', currency }).format(cents / 100);
}

formatPrice(1999); // '$19.99'
formatPrice('1999'); // Error: Argument of type 'string' is not assignable to parameter of type 'number'.

interface Address {
  city: string;
  country: string;
}

interface User {
  readonly id: number;
  name: string;
  email: string;
  address?: Address; // may be missing
  tags: string[];
}

function describeUser(user: User): string {
  const place = user.address ? ` from ${user.address.city}` : '';
  return `${user.name}${place} (${user.tags.length} tags)`;
}

const asha: User = { id: 1, name: 'Asha', email: 'asha@example.com', tags: ['admin'] };
describeUser(asha); // 'Asha (1 tags)'
asha.id = 2; // Error: Cannot assign to 'id' because it is a read-only property.

// The same shape, either way.
type Point = { x: number; y: number };
interface PointShape {
  x: number;
  y: number;
}

// Only a type alias can name a union.
type Id = string | number;

// Building on another type: extends for interfaces, & for type aliases.
interface Person {
  name: string;
}
interface Employee extends Person {
  team: string;
}
type Contractor = Person & { agency: string };

const lead: Employee = { name: 'Asha', team: 'web' };
const designer: Contractor = { name: 'Ben', agency: 'Studio North' };

type Variant = 'primary' | 'secondary' | 'ghost';
type Size = 'sm' | 'md' | 'lg';

function buttonClass(variant: Variant, size: Size = 'md'): string {
  return `button button--${variant} button--${size}`;
}

buttonClass('primary'); // 'button button--primary button--md'
buttonClass('danger'); // Error: Argument of type '"danger"' is not assignable to parameter of type 'Variant'.

const ROLES = ['viewer', 'editor', 'admin'] as const;
type Role = (typeof ROLES)[number]; // 'viewer' | 'editor' | 'admin'

function isRole(value: string): value is Role {
  return (ROLES as readonly string[]).includes(value);
}

// A value from outside is just a string until it is checked.
const fromUrl = new URLSearchParams(location.search).get('role') ?? '';
const role: Role = isRole(fromUrl) ? fromUrl : 'viewer';

interface User {
  id: number;
  name: string;
}

function greeting(user: User | null): string {
  return user ? `Welcome back, ${user.name}` : 'Sign in to save your progress';
}

function firstName(user: User | null): string {
  return user?.name.split(' ')[0] ?? 'Guest';
}

function initial(user: User | null): string {
  return user.name.charAt(0); // Error: 'user' is possibly 'null'.
}

function formatValue(value: string | number | Date | null): string {
  if (value === null) return '—';
  if (typeof value === 'number') return value.toFixed(2); // value: number
  if (value instanceof Date) return value.toISOString().slice(0, 10); // value: Date
  return value.trim(); // value: string, the only type left
}

formatValue(3.14159); // '3.14'
formatValue(new Date(Date.UTC(2026, 8, 29))); // '2026-09-29'

type Circle = { radius: number };
type Rectangle = { width: number; height: number };

function area(shape: Circle | Rectangle): number {
  if ('radius' in shape) return Math.PI * shape.radius ** 2; // shape: Circle
  return shape.width * shape.height; // shape: Rectangle
}

area({ radius: 1 }); // 3.141592653589793
area({ width: 2, height: 3 }); // 6

interface User {
  id: number;
  name: string;
}

function isUser(value: unknown): value is User {
  return (
    typeof value === 'object' &&
    value !== null &&
    'id' in value &&
    typeof value.id === 'number' &&
    'name' in value &&
    typeof value.name === 'string'
  );
}

async function loadUser(id: number): Promise<User> {
  const response = await fetch(`/api/users/${id}`);
  const data: unknown = await response.json();
  if (!isUser(data)) throw new Error(`/api/users/${id} did not answer with a user`);
  return data; // data: User
}

function first<T>(items: readonly T[]): T | undefined {
  return items[0];
}

function last<T>(items: readonly T[]): T | undefined {
  return items[items.length - 1];
}

const lowest = first([3, 1, 2]); // lowest: number | undefined
const newest = last(['draft', 'review', 'live']); // newest: string | undefined

