function sortBy<T, K extends keyof T>(items: readonly T[], key: K): T[] {
  return items.toSorted((a, b) => (a[key] < b[key] ? -1 : a[key] > b[key] ? 1 : 0));
}

const people = [
  { name: 'Sam', age: 31 },
  { name: 'Asha', age: 27 },
];

sortBy(people, 'age'); // [{ name: 'Asha', age: 27 }, { name: 'Sam', age: 31 }]
sortBy(people, 'email'); // Error: Argument of type '"email"' is not assignable to parameter of type '"age" | "name"'.

interface User {
  id: number;
  name: string;
}

// Before: three flags make 8 combinations, and only 4 of them are real states.
interface UsersState {
  isLoading: boolean;
  error?: string;
  users?: User[];
}

// After: exactly the 4 real states, each carrying only what it has.
type UsersRequest =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; users: User[] }
  | { status: 'error'; message: string };

const broken: UsersState = { isLoading: true, error: 'Timeout' }; // allowed, but meaningless
const impossible: UsersRequest = { status: 'loading', message: 'Timeout' }; // Error: Object literal may only specify known properties, and 'message' does not exist in type '{ status: "loading"; }'.

interface User {
  id: number;
  name: string;
}

type UsersRequest =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; users: User[] }
  | { status: 'error'; message: string };

function UsersPanel({ request, onLoad }: { request: UsersRequest; onLoad: () => void }) {
  switch (request.status) {
    case 'idle':
      return (
        <button type="button" onClick={onLoad}>
          Load users
        </button>
      );
    case 'loading':
      return <p role="status">Loading…</p>;
    case 'error':
      return <p role="alert">{request.message}</p>;
    case 'success':
      return (
        <ul>
          {request.users.map((user) => (
            <li key={user.id}>{user.name}</li>
          ))}
        </ul>
      );
  }
}

interface User {
  id: number;
  name: string;
}

type UsersRequest =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; users: User[] }
  | { status: 'error'; message: string };

type Action = { type: 'fetch' } | { type: 'resolve'; users: User[] } | { type: 'reject'; message: string };

function reducer(state: UsersRequest, action: Action): UsersRequest {
  switch (action.type) {
    case 'fetch':
      return { status: 'loading' };
    case 'resolve':
      return { status: 'success', users: action.users };
    case 'reject':
      return { status: 'error', message: action.message };
    default: {
      // Add an action type without a case, and this line stops compiling.
      const unhandled: never = action;
      return unhandled;
    }
  }
}
